function getTodayIdx(phase) {
  var dow = new Date().getDay();
  if (phase == 4) {
    var m6 = { 1:0, 2:1, 3:2, 4:3, 5:4, 6:5 }; // Mon-Sat
    return m6[dow] !== undefined ? m6[dow] : 0;
  }
  var m4 = { 1:0, 2:1, 4:2, 5:3 }; // Mon, Tue, Thu, Fri
  return m4[dow] !== undefined ? m4[dow] : 0;
}
